--
-- Table structure for table `machinestagehistory`
--

DROP TABLE IF EXISTS `machinestagehistory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `machinestagehistory` (
  `id` varchar(191) NOT NULL,
  `machineId` varchar(191) NOT NULL,
  `stage` int(11) NOT NULL,
  `operationSeqNo` varchar(191) NOT NULL,
  `workCenter` varchar(191) DEFAULT NULL,
  `startedAt` datetime(3) DEFAULT NULL,
  `endedAt` datetime(3) DEFAULT NULL,
  `completedQty` varchar(191) DEFAULT NULL,
  `isCompleted` tinyint(1) NOT NULL DEFAULT 0,
  `source` enum('PLANT_SYNC','MANUAL') NOT NULL DEFAULT 'PLANT_SYNC',
  `syncedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `MachineStageHistory_machineId_operationSeqNo_source_key` (`machineId`,`operationSeqNo`,`source`),
  KEY `MachineStageHistory_machineId_stage_idx` (`machineId`,`stage`),
  CONSTRAINT `MachineStageHistory_machineId_fkey` FOREIGN KEY (`machineId`) REFERENCES `machine` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

